create table users (id uuid primary key, email text unique not null, full_name text, avatar_url text, created_at timestamptz default now());
create table workspaces (id uuid primary key, owner_id uuid references users(id), name text not null, created_at timestamptz default now());
create table projects (id uuid primary key, workspace_id uuid references workspaces(id), parent_project_id uuid references projects(id), name text not null, color text, icon text, is_archived boolean default false, position numeric, created_at timestamptz default now());
create table sections (id uuid primary key, project_id uuid references projects(id), name text not null, position numeric, created_at timestamptz default now());
create table labels (id uuid primary key, workspace_id uuid references workspaces(id), name text not null, color text, created_at timestamptz default now());
create table tasks (id uuid primary key, workspace_id uuid references workspaces(id), project_id uuid references projects(id), section_id uuid references sections(id), parent_task_id uuid references tasks(id), creator_id uuid references users(id), assignee_id uuid references users(id), title text not null, description_rich jsonb, status text not null default 'active', priority int default 4, due_date date, due_time time, deadline_date date, recurrence_rule text, recurrence_mode text, source_type text, source_payload jsonb, order_index numeric, energy_estimate int, duration_estimate int, custom_fields jsonb, is_archived boolean default false, created_at timestamptz default now(), updated_at timestamptz default now(), completed_at timestamptz);
create table task_labels (task_id uuid references tasks(id) on delete cascade, label_id uuid references labels(id) on delete cascade, primary key (task_id, label_id));
create table reminders (id uuid primary key, task_id uuid references tasks(id) on delete cascade, reminder_type text not null, remind_at timestamptz, location_payload jsonb, created_at timestamptz default now());
create table comments (id uuid primary key, task_id uuid references tasks(id) on delete cascade, user_id uuid references users(id), body text not null, created_at timestamptz default now());
create table attachments (id uuid primary key, task_id uuid references tasks(id) on delete cascade, file_name text not null, file_url text not null, mime_type text, file_size bigint, created_at timestamptz default now());
create table filters (id uuid primary key, workspace_id uuid references workspaces(id), name text not null, color text, query_text text, visual_config jsonb, is_favorite boolean default false, created_at timestamptz default now());
create table activity_logs (id uuid primary key, task_id uuid references tasks(id) on delete cascade, actor_id uuid references users(id), action_type text not null, payload jsonb, created_at timestamptz default now());
create table notifications (id uuid primary key, workspace_id uuid references workspaces(id), task_id uuid references tasks(id) on delete cascade, user_id uuid references users(id), notification_type text not null, payload jsonb, read_at timestamptz, created_at timestamptz default now());
create table widget_configs (id uuid primary key, user_id uuid references users(id), workspace_id uuid references workspaces(id), view_type text not null, config jsonb, created_at timestamptz default now());
create table smart_suggestions (id uuid primary key, workspace_id uuid references workspaces(id), task_id uuid references tasks(id) on delete cascade, suggestion_type text not null, payload jsonb, accepted_at timestamptz, dismissed_at timestamptz, created_at timestamptz default now());
create index tasks_workspace_status_due_idx on tasks(workspace_id, status, due_date);
create index tasks_project_idx on tasks(project_id, section_id, order_index);
create index activity_logs_task_idx on activity_logs(task_id, created_at desc);
create index filters_workspace_favorite_idx on filters(workspace_id, is_favorite);
